function loadHistory():Attempt[]{try{const saved=JSON.parse(localStorage.getItem(historyKey)||'[]');if(Array.isArray(saved))return saved;if(saved?.v===2&&Array.isArray(saved.d))return saved.d.map((x:string[])=>({id:x[0],subject:x[1],score:Number(x[2]),total:Number(x[3]),correct:Number(x[4]),wrong:Number(x[5]),date:x[6],durationSeconds:Number(x[7])||undefined}));return []}catch{return []}}
function compactHistory(items:Attempt[]){return {v:2,d:items.slice(0,50).map(h=>[h.id,h.subject,h.score,h.total,h.correct,h.wrong,h.date,h.durationSeconds||0])}}
function localizedName(item:{nome:string;traduzioni?:Record<string,{nome?:string}>},_language:Language){return item.traduzioni?.it?.nome||item.nome}
function localizedQuestion(q:Question,_language:Language):Question{return q}
function normalizeOptionText(value:string){return value.normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase('it')}
function findOptionIndex(options:string[],answer:string|undefined){if(!answer)return -1;const raw=answer.trim(),target=normalizeOptionText(raw);const exact=options.findIndex(option=>normalizeOptionText(option)===target);if(exact>=0)return exact;return /^[A-D]$/i.test(raw)?'ABCD'.indexOf(raw.toUpperCase()):-1}
function correctOptionIndex(question:Question){const byAnswer=findOptionIndex(question.opzioni||[],question.risposta_corretta);if(byAnswer>=0)return byAnswer;if(Number.isInteger(question.correct_index)&&question.correct_index!>=0&&question.correct_index!<(question.opzioni||[]).length)return question.correct_index!;return -1}
function dateLabel(value:string){return new Intl.DateTimeFormat('it-IT',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(value))}

type QuizTimerProps={started:number|null;totalSeconds:number;paused:boolean;enabled:boolean;secondsRef:{current:number};onExpireRef:{current:()=>void}}
const QuizTimer=memo(function QuizTimer({started,totalSeconds,paused,enabled,secondsRef,onExpireRef}:QuizTimerProps){
 const [seconds,setSeconds]=useState(()=>Math.max(0,secondsRef.current));
 useEffect(()=>{
  if(!enabled||!started||paused)return;
  let expired=false;
  const tick=()=>{
   const remaining=Math.max(0,totalSeconds-Math.floor((Date.now()-started)/1000));
   secondsRef.current=remaining;
   setSeconds(previous=>previous===remaining?previous:remaining);
   if(remaining===0&&!expired){expired=true;onExpireRef.current()}
  };
  tick();
  const timer=window.setInterval(tick,1000);
  return()=>window.clearInterval(timer);
 },[enabled,started,totalSeconds,paused,secondsRef,onExpireRef]);
 return <div className="timer"><Clock3 size={15}/>{String(Math.floor(seconds/60)).padStart(2,'0')}:{String(seconds%60).padStart(2,'0')}</div>
})

