 async function startQuiz(s:Subject){
  if(!user){requireLogin();return}
  if(!supabase)return;
  setBusy(true);
  try{
   // Carica i soli quiz della materia scelta: non scaricare l'intero archivio all'apertura del sito.
   const [{data:readySetsData,error:readySetsError},{data:completedRows,error:completedError}]=await Promise.all([
    supabase.from('quiz_sets').select('id,materia_id,quiz_number,status,question_count').eq('materia_id',s.id).eq('status','ready').eq('question_count',10).order('quiz_number'),
    supabase.from('quiz_attempts').select('quiz_set_id').eq('user_id',user.id).eq('materia_id',s.id).eq('status','completed').not('quiz_set_id','is',null)
   ]);
   if(readySetsError)throw readySetsError;
   if(completedError)throw completedError;
   const readySets=(readySetsData||[]) as QuizSet[];
   const completedSetIds=new Set((completedRows||[]).map((row:any)=>row.quiz_set_id).filter(Boolean));
   const firstUncompleted=readySets.find(q=>!completedSetIds.has(q.id));
   // Non avviare una generazione che il server non può completare: mostrare subito
   // un messaggio chiaro quando tutti i quiz già pronti sono stati completati.
   if(!firstUncompleted){
    if(readySets.length>0){setCatalogExhaustedSubject(s);setSubject(s)}
    else notify(tr('generationPending'));
    return;
   }
   setCatalogExhaustedSubject(null);
   // Solo dopo aver verificato che esista un quiz disponibile abbandoniamo
   // l'eventuale sessione in pausa dell'utente.
   localStorage.removeItem('smlquiz.active-quiz.v1');
   setAttemptId(null);setQuestions([]);setIndex(0);setChoice(null);setAnswerFeedback(null);setRevealed(false);setCorrect(0);setWrong(0);setWrongQuestions([]);setQuizResponses({});setCompletedReview([]);setStarted(null);setQuizPaused(false);setQuizDismissed(false);setReviewMode(false);
   setSubject(s);
   const quizSetId=firstUncompleted.id;
   const idempotencyKey=crypto.randomUUID();
   let data:any=null;
   for(let retry=0;retry<2;retry++){
    const result=await supabase.functions.invoke('quiz-api',{body:{action:'start',materiaId:s.id,quizSetId,idempotencyKey,language}});
    if(!result.error){data=result.data;break}
    if(retry===1)throw result.error;
    await new Promise(resolve=>window.setTimeout(resolve,700));
   }
   if(data?.error)throw new Error(data.error);
   if(data?.language!==language)throw new Error('La lingua della simulazione non corrisponde a quella selezionata. Riprova.');
   if(!Array.isArray(data?.questions)||data.questions.length!==10)throw new Error(tr('quizInvalidQuestionCount'));
   setAttemptId(data.attemptId);setQuizPaused(false);setQuizDismissed(false);setQuestions((data.questions as Question[]).map(q=>localizedQuestion(q,language)));setIndex(0);setChoice(null);setAnswerFeedback(null);setRevealed(false);setCorrect(0);setWrong(0);setWrongQuestions([]);setReviewMode(false);secondsRef.current=(data.questions?.length||10)*45;setStarted(Date.now());setPage('home');void refreshWallet()
  }catch(err){
   const message=err instanceof Error?err.message:tr('loadQuestionsFailed');
   notify(message);
   if(message.toLowerCase().includes('terminato i 5 quiz')||message.toLowerCase().includes('esaurito'))setUpsellOpen(true)
  }finally{setBusy(false)}
 }
 async function startErrorReview(){
  if(!user){requireLogin();return}
  if(!supabase)return;
  setBusy(true);
  try{
   const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'wrong-questions'}});
   if(error)throw error;
   if(data?.error)throw new Error(data.error);
   const missed=Array.isArray(data?.questions)?(data.questions as Question[]):[];
   setReviewQuestions(missed);
   if(!missed.length){notify(tr('noErrorsArchive'));return}
   localStorage.removeItem('smlquiz.active-quiz.v1');
   setAttemptId(null);setSubject(null);setQuestions(missed.map(q=>localizedQuestion(q,'it')));
   setIndex(0);setChoice(null);setAnswerFeedback(null);setRevealed(false);
   setCorrect(0);setWrong(0);setWrongQuestions([]);setQuizResponses({});setCompletedReview([]);setReviewMode(true);
   setQuizPaused(false);setQuizDismissed(false);secondsRef.current=missed.length*45;
   setStarted(Date.now());setPage('home');
   window.history.pushState({page:'home'},'','/quiz');
  }catch(err){notify(err instanceof Error?err.message:tr('loadQuestionsFailed'))}
  finally{setBusy(false)}
 }
 async function submit(){
  if(answerSubmittingRef.current||!user){if(!user)requireLogin();return}
  if(choice===null||!current||revealed)return;
  const selectedAnswer=current.opzioni?.[choice];
  if(!selectedAnswer){notify('La risposta selezionata non è valida.');return}
  answerSubmittingRef.current=true;
  if(reviewMode){
   const correctIndex=correctOptionIndex(current);
   if(correctIndex<0){notify('Questa domanda non ha una risposta corretta associata alle opzioni.');answerSubmittingRef.current=false;return}
   const correctAnswer=current.opzioni[correctIndex],selectedLetter=String.fromCharCode(65+choice),correctLetter=String.fromCharCode(65+correctIndex),good=choice===correctIndex;
   setAnswerFeedback({correct:good,correctAnswer,correctIndex,correctLetter,selectedLetter,explanation:current.spiegazione||null});
   setQuizResponses(v=>({...v,[current.id]:{selectedAnswer,selectedLetter,correctAnswer,correctLetter,correctIndex,isCorrect:good,explanation:current.spiegazione||null}}));
   setSavedQuestions(v=>v.map(q=>q.id===current.id?{...q,risposta_corretta:correctAnswer,correct_index:correctIndex}:q));
   if(good)setCorrect(v=>v+1);else{setWrong(v=>v+1);setWrongQuestions(v=>[...v.filter(q=>q.id!==current.id),current])}
   setRevealed(true);answerSubmittingRef.current=false;return;
  }
  if(!attemptId||!supabase){answerSubmittingRef.current=false;return}
  setBusy(true);
  try{
   let data:any=null;
   for(let retry=0;retry<2;retry++){
    const result=await supabase.functions.invoke('quiz-api',{body:{action:'answer',attemptId,questionId:current.id,selectedAnswer,language}});
    if(!result.error){data=result.data;break}
    if(retry===1)throw result.error;
    await new Promise(resolve=>window.setTimeout(resolve,700));
   }
   if(data?.error)throw new Error(data.error);
   if(data?.saved!==true)throw new Error('La risposta non è stata registrata. Riprova.');
   // Durante il quiz il client riceve soltanto la conferma di salvataggio.
   // Soluzioni, esito e spiegazioni arrivano esclusivamente alla consegna finale.
   setAnswerFeedback(null);
   setRevealed(true);
  }catch(err){notify(err instanceof Error?err.message:tr('answerSaveFailed'))}
  finally{setBusy(false);answerSubmittingRef.current=false}
 }
 
