 async function finish(){if(!user){setQuestions([]);setAttemptId(null);setStarted(null);requireLogin();return}if(reviewMode){setReviewQuestions(wrongQuestions);setWrongQuestions([]);setQuestions([]);setStarted(null);setReviewMode(false);setPage('progress');notify(wrongQuestions.length?tr('reviewStillRemaining').replace('{n}',String(wrongQuestions.length)):tr('reviewCompleted'));return}if(!attemptId||!supabase)return;try{const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'finish',attemptId,language}});if(error)throw error;if(data?.error)throw new Error(data.error);setCompletedReview(Array.isArray(data.review)?data.review.map((item:any)=>({question:item.question as Question,response:item.response as QuizResponse|null})):questions.map(question=>({question,response:quizResponses[question.id]||null})));const elapsedSeconds=started?Math.max(0,Math.floor((Date.now()-started)/1000)):Math.max(0,45*questions.length-secondsRef.current);const item:Attempt={id:attemptId,subject:subject?localizedName(subject,language):'Quiz',score:Number(data.score),total:Number(data.total),correct:Number(data.correct),wrong:Number(data.wrong),date:new Date().toISOString(),durationSeconds:elapsedSeconds};setHistory(v=>[item,...v.filter(x=>x.id!==item.id)]);setLastResult(item);setLeaderboardMateriaId(subject?.id||'');localStorage.removeItem('smlquiz.active-quiz.v1');setReviewQuestions(v=>{const all=new Map(v.map(q=>[q.id,q]));for(const q of wrongQuestions)all.set(q.id,q);return [...all.values()]});setWrongQuestions([]);void refreshWrongQuestions();void refreshWeakTopics();setQuestions([]);setStarted(null);setAttemptId(null);setQuizPaused(false);setPage('result');notify(tr('quizCompletedPoints').replace('{n}',item.score.toFixed(2)));await refreshWallet()}catch(err){notify(err instanceof Error?err.message:tr('quizSaveFailed'))}}
 finishRef.current=()=>{void finish()}
 function shareUrl(h:Attempt){const url=new URL(location.origin);const matched=subjects.find(s=>s.nome===h.subject||localizedName(s,language)===h.subject);url.searchParams.set('share','quiz');url.searchParams.set('challenge','1');url.searchParams.set('materia_id',matched?.id||subject?.id||'');url.searchParams.set('subject',localizedName(matched||{nome:h.subject},language));url.searchParams.set('score',h.score.toFixed(2));url.searchParams.set('correct',String(h.correct));url.searchParams.set('total',String(h.total));if(typeof h.durationSeconds==='number')url.searchParams.set('duration_seconds',String(h.durationSeconds));return url.toString()}
