 function acceptSharedChallenge(){if(!sharedChallenge)return;if(!user){requireLogin();return}const target=subjects.find(s=>s.id===sharedChallenge.materiaId);if(!target){notify(tr('challengeSubjectUnavailable'));return}void startQuiz(target)}
 const validExams=exams.map(e=>({name:e.name,g:Number(e.grade),c:Number(e.cfu)})).filter(e=>Number.isFinite(e.g)&&e.g>=18&&e.g<=30&&Number.isFinite(e.c)&&e.c>0);
 const totalCfu=validExams.reduce((sum,e)=>sum+e.c,0);
