 <label className="consent digital-consent buy-global-consent"><input type="checkbox" checked={digitalConsent} onChange={e=>setDigitalConsent(e.target.checked)}/>{tr('digitalContentConsent')}</label>
 {(wallet.activeSiteSubscription||wallet.activeSubjectEntitlements?.length)&&<div className="panel active-entitlements-panel"><div className="panel-title"><div><h3>I tuoi accessi attivi</h3><p>Controlla quali accessi sono validi e quando terminano.</p></div><CheckCircle2/></div>{wallet.activeSiteSubscription&&<div className="active-entitlement-row"><div><strong>Accesso a tutto il sito</strong><small>{wallet.activeSiteSubscription.cancel_at_period_end?'Disdetta programmata':'Abbonamento attivo'}</small></div><b>{wallet.activeSiteSubscription.current_period_end?'Fino al '+dateLabel(wallet.activeSiteSubscription.current_period_end):'Attivo'}</b></div>}{(wallet.activeSubjectEntitlements||[]).map(entitlement=><div className="active-entitlement-row" key={entitlement.id}><div><strong>{localizedName(subjects.find(x=>x.id===entitlement.materia_id)||{nome:entitlement.materia_id},language)}</strong><small>{entitlement.entitlement_type==='session'?'Pass Sessione':'Pass Singola Materia'}</small></div><b>{entitlement.expires_at==='infinity'||entitlement.expires_at.startsWith('9999')?'Accesso permanente':'Fino al '+dateLabel(entitlement.expires_at)}</b></div>)}</div>}
